<?php
namespace App\Http\Controllers;

use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Yajra\DataTables\Facades\DataTables;

class DataTableController extends Controller
{
    public function __invoke(Request $request,string $resource)
    {
        $user=$request->user();
        $permission=match($resource){'users'=>'users.view','roles'=>'roles.manage','shifts'=>'shifts.view','rates'=>'rates.view','invoices'=>'invoices.view','customers'=>'customers.view','expenses'=>'expenses.view','fuels'=>'setup.manage','nozzles'=>'setup.manage','shift-types'=>'setup.manage',default=>null};
        abort_unless($permission && $user->hasPermission($permission),403);
        $ids=$user->role==='Super Admin'?DB::table('stations')->where('active',true)->pluck('id'):$user->stations()->where('stations.active',true)->pluck('stations.id');
        $stationNames="COALESCE((SELECT GROUP_CONCAT(stations.name SEPARATOR ', ') FROM station_user JOIN stations ON stations.id=station_user.station_id WHERE station_user.user_id=users.id),'All stations') as station_names";
        $query=match($resource){
            'users'=>DB::table('users')->leftJoin('roles','roles.id','=','users.role_id')->when($user->role!=='Super Admin',fn($q)=>$q->whereExists(fn($stationQuery)=>$stationQuery->selectRaw('1')->from('station_user')->whereColumn('station_user.user_id','users.id')->whereIn('station_user.station_id',$ids)))->select('users.id','users.name','users.email','users.mobile','users.role','users.active','roles.name as role_name',DB::raw($stationNames))->orderBy('users.name'),
            'roles'=>DB::table('roles')->leftJoin('permission_role','permission_role.role_id','=','roles.id')->leftJoin('users','users.role_id','=','roles.id')->groupBy('roles.id','roles.name','roles.description','roles.system','roles.active')->select('roles.id','roles.name','roles.description','roles.system','roles.active',DB::raw('COUNT(DISTINCT permission_role.permission_id) as permissions_count'),DB::raw('COUNT(DISTINCT users.id) as users_count'))->orderBy('roles.name'),
            'shifts'=>DB::table('shift_readings')->join('shifts','shifts.id','=','shift_readings.shift_id')->join('stations','stations.id','=','shifts.station_id')->join('shift_types','shift_types.id','=','shifts.shift_type_id')->join('users','users.id','=','shifts.operator_id')->join('nozzles','nozzles.id','=','shift_readings.nozzle_id')->join('fuel_types','fuel_types.id','=','shift_readings.fuel_type_id')->whereIn('shifts.station_id',$ids)->select('shifts.id as shift_id','shifts.station_id','shifts.operator_id','shift_readings.id as reading_id','shifts.shift_date as date','shift_types.name as shift','users.name as operator','nozzles.name as nozzle','fuel_types.name as fuel','fuel_types.unit','shift_readings.opening_reading as opening','shift_readings.closing_reading as closing','shift_readings.quantity','shift_readings.amount','shifts.status')->orderByDesc('shifts.shift_date'),
            'rates'=>DB::table('daily_rates')->join('stations','stations.id','=','daily_rates.station_id')->join('fuel_types','fuel_types.id','=','daily_rates.fuel_type_id')->leftJoin('users','users.id','=','daily_rates.updated_by')->whereIn('daily_rates.station_id',$ids)->select('daily_rates.id','daily_rates.rate_date as date','stations.name as station','fuel_types.name as fuel','fuel_types.unit','daily_rates.rate','users.name as author')->orderByDesc('daily_rates.rate_date'),
            'invoices'=>DB::table('invoices')->join('stations','stations.id','=','invoices.station_id')->leftJoin('customers','customers.id','=','invoices.customer_id')->whereIn('invoices.station_id',$ids)->select('invoices.id','invoices.invoice_number','invoices.invoice_date as date','customers.name as customer','stations.name as station','invoices.grand_total as total','invoices.paid_amount as paid',DB::raw('(invoices.grand_total-invoices.paid_amount) as due'),'invoices.status')->orderByDesc('invoices.invoice_date'),
            'customers'=>DB::table('customers')->leftJoin('customer_ledgers','customers.id','=','customer_ledgers.customer_id')->whereIn('customers.station_id',$ids)->where('customers.active',true)->groupBy('customers.id','customers.name','customers.mobile','customers.credit_limit','customers.opening_balance')->select('customers.id','customers.name','customers.mobile','customers.credit_limit',DB::raw('COALESCE(SUM(customer_ledgers.debit-customer_ledgers.credit),customers.opening_balance) as outstanding'))->orderBy('customers.name'),
            'expenses'=>DB::table('expenses')->join('stations','stations.id','=','expenses.station_id')->join('expense_categories','expense_categories.id','=','expenses.category_id')->join('users','users.id','=','expenses.created_by')->whereNull('expenses.deleted_at')->whereIn('expenses.station_id',$ids)->select('expenses.id','expenses.expense_date as date','stations.name as station','expense_categories.name as category','expenses.amount','expenses.payment_mode as mode','users.name as creator')->orderByDesc('expenses.expense_date'),
            'fuels'=>DB::table('fuel_types')->select('id','name','unit','hsn_code','tax_rate','active')->orderBy('name'),
            'nozzles'=>DB::table('nozzles')->join('fuel_types','fuel_types.id','=','nozzles.fuel_type_id')->leftJoin('dispensers','dispensers.id','=','nozzles.dispenser_id')->whereIn('nozzles.station_id',$ids)->when($request->integer('station_id'),fn($q)=>$q->where('nozzles.station_id',$request->integer('station_id')))->select('nozzles.id','nozzles.name','nozzles.station_id','nozzles.fuel_type_id','fuel_types.name as fuel','dispensers.name as dispenser','nozzles.active')->orderBy('nozzles.name'),
            'shift-types'=>DB::table('shift_types')->whereIn('station_id',$ids)->when($request->integer('station_id'),fn($q)=>$q->where('station_id',$request->integer('station_id')))->select('id','station_id','name','starts_at','ends_at','active')->orderBy('starts_at'),
        };
        $table=DataTables::query($query);
        if($resource==='users')$table->addColumn('contact',fn($row)=>e($row->email).($row->mobile?'<div class="text-muted small">'.e($row->mobile).'</div>':''))->addColumn('status',fn($row)=>$row->active?'Active':'Inactive')->addColumn('actions',fn($row)=>$user->hasPermission('users.manage')?'<div class="d-flex gap-1"><a class="btn btn-sm btn-light" href="'.route('users.edit',$row->id).'">Edit</a>'.($row->active&&$row->id!==$user->id?'<form method="post" action="'.route('users.deactivate',$row->id).'">'.csrf_field().method_field('delete').'<button class="btn btn-sm btn-light">Deactivate</button></form>':'').'</div>':'');
        if($resource==='roles')$table->addColumn('type',fn($row)=>$row->system?'Built-in':'Custom')->addColumn('status',fn($row)=>$row->active?'Active':'Inactive')->addColumn('actions',fn($row)=>'<div class="d-flex gap-1"><a class="btn btn-sm btn-light" href="'.route('roles.edit',$row->id).'">Edit</a>'.(!$row->system&&!(int)$row->users_count?'<form method="post" action="'.route('roles.destroy',$row->id).'">'.csrf_field().method_field('delete').'<button class="btn btn-sm btn-light">Delete</button></form>':'').'</div>');
        if($resource==='invoices')$table->addColumn('actions',fn($row)=>'<div class="d-flex gap-1"><a class="btn btn-sm btn-light" href="'.route('invoices.show',$row->id).'">View</a>'.($user->hasPermission('invoices.manage')&&$row->status==='Issued'?'<form method="post" action="'.route('invoices.void',$row->id).'" onsubmit="return confirm(\'Void this invoice and reverse its customer ledger entry?\')">'.csrf_field().method_field('delete').'<input class="form-control form-control-sm mb-1" name="void_reason" placeholder="Reason for void" required><button class="btn btn-sm btn-outline-danger">Void</button></form>':'').'</div>');
        if($resource==='shifts')$table->addColumn('actions',function($row)use($user){if($row->reading_id!==DB::table('shift_readings')->where('shift_id',$row->shift_id)->min('id'))return '';if($row->status==='Open'&&(($row->operator_id===$user->id&&$user->hasPermission('shifts.close'))||($user->hasPermission('shifts.manage')&&($user->role==='Super Admin'||$user->stations()->where('stations.id',$row->station_id)->exists())))){$readings=DB::table('shift_readings')->join('nozzles','nozzles.id','=','shift_readings.nozzle_id')->where('shift_id',$row->shift_id)->select('shift_readings.id','shift_readings.opening_reading','nozzles.name')->get();$html='<details><summary class="btn btn-sm btn-light">Close shift</summary><form method="post" action="'.route('shifts.close',$row->shift_id).'">'.csrf_field().'<div class="row g-2 mt-1">';foreach($readings as $reading)$html.='<div class="col-12"><label class="form-label">'.e($reading->name).' closing</label><input class="form-control form-control-sm" name="readings['.$reading->id.'][closing]" type="number" min="'.$reading->opening_reading.'" step="0.001" required></div>';foreach(['cash_collected'=>'Cash','upi_collected'=>'UPI','bank_collected'=>'Bank','card_collected'=>'Card','credit_sales'=>'Credit'] as $field=>$label)$html.='<div class="col-6"><label class="form-label">'.e($label).' ₹</label><input class="form-control form-control-sm" name="'.$field.'" type="number" value="0" min="0" step="0.01" required></div>';$html.='<div class="col-12"><label class="form-label">Remarks</label><input class="form-control form-control-sm" name="remarks" maxlength="2000"></div><div class="col-12"><button class="btn btn-sm btn-primary">Submit for approval</button></div></div></form></details>';if($user->hasPermission('shifts.manage'))$html.='<form class="mt-1" method="post" action="'.route('shifts.void',$row->shift_id).'">'.csrf_field().method_field('delete').'<input name="reason" class="form-control form-control-sm mb-1" placeholder="Reason to void" required><button class="btn btn-sm btn-outline-danger">Void open shift</button></form>';return $html;}if($row->status==='Submitted'&&$user->hasPermission('shifts.manage')&&($user->role==='Super Admin'||$user->stations()->where('stations.id',$row->station_id)->exists()))return '<form class="d-flex gap-1" method="post" action="'.route('shifts.decision',$row->shift_id).'">'.csrf_field().'<input type="hidden" name="remarks" value="Reviewed"><button class="btn btn-sm btn-primary" name="decision" value="Approved">Approve</button><button class="btn btn-sm btn-outline-danger" name="decision" value="Rejected">Reject</button></form>';return '';});
        if($resource==='expenses')$table->addColumn('actions',fn($row)=>$user->hasPermission('expenses.manage')?'<div class="d-flex gap-1"><a class="btn btn-sm btn-light" href="'.route('expenses.edit',$row->id).'">Edit</a><form method="post" action="'.route('expenses.destroy',$row->id).'" onsubmit="return confirm(\'Void this expense?\')">'.csrf_field().method_field('delete').'<button class="btn btn-sm btn-light">Void</button></form></div>':'');
        if($resource==='customers')$table->addColumn('receipt',fn($row)=>$user->hasPermission('customers.manage')?'<div class="d-flex flex-wrap gap-1 align-items-center"><a class="btn btn-sm btn-light" href="'.route('customers.edit',$row->id).'">Edit</a><form method="post" action="'.route('customers.deactivate',$row->id).'">'.csrf_field().method_field('delete').'<button class="btn btn-sm btn-light">Deactivate</button></form><form class="d-flex gap-1" method="post" action="'.route('customers.receipt',$row->id).'">'.csrf_field().'<input name="amount" type="number" class="form-control form-control-sm" min="0.01" step="0.01" placeholder="Receipt ₹" required><input type="hidden" name="payment_date" value="'.now()->toDateString().'"><input type="hidden" name="mode" value="Cash"><button class="btn btn-sm btn-light">Add receipt</button></form></div>':'');
        if($resource==='fuels')$table->addColumn('actions',fn($row)=>'<form method="post" action="'.route('setup.fuels.update',$row->id).'">'.csrf_field().method_field('put').'<input class="form-control form-control-sm mb-1" name="name" value="'.e($row->name).'" required><input class="form-control form-control-sm mb-1" name="unit" value="'.e($row->unit).'" required><input class="form-control form-control-sm mb-1" name="hsn_code" value="'.e($row->hsn_code??'').'" placeholder="HSN code"><input class="form-control form-control-sm mb-1" type="number" step=".01" min="0" max="100" name="tax_rate" value="'.$row->tax_rate.'" required><label class="d-flex gap-2 align-items-center"><input type="checkbox" name="active" value="1" '.($row->active?'checked':'').'>Active</label><button class="btn btn-sm btn-light mt-1">Save</button></form>');
        if($resource==='nozzles')$table->addColumn('actions',function($row){$options='';foreach(DB::table('fuel_types')->where('active',true)->orderBy('name')->get() as $fuel)$options.='<option value="'.$fuel->id.'" '.($fuel->id===$row->fuel_type_id?'selected':'').'>'.e($fuel->name).'</option>';return '<form method="post" action="'.route('setup.nozzles.update',$row->id).'">'.csrf_field().method_field('put').'<input class="form-control form-control-sm mb-1" name="name" value="'.e($row->name).'" required><select class="form-select form-select-sm mb-1" name="fuel_type_id">'.$options.'</select><input class="form-control form-control-sm mb-1" name="dispenser" value="'.e($row->dispenser??'').'" placeholder="Dispenser"><label class="d-flex gap-2 align-items-center"><input type="checkbox" name="active" value="1" '.($row->active?'checked':'').'>Active</label><button class="btn btn-sm btn-light mt-1">Save</button></form>';});
        if($resource==='shift-types')$table->addColumn('actions',fn($row)=>'<form method="post" action="'.route('setup.shifts.update',$row->id).'">'.csrf_field().method_field('put').'<input class="form-control form-control-sm mb-1" name="name" value="'.e($row->name).'" required><input class="form-control form-control-sm mb-1" type="time" name="starts_at" value="'.substr($row->starts_at,0,5).'" required><input class="form-control form-control-sm mb-1" type="time" name="ends_at" value="'.substr($row->ends_at,0,5).'" required><label class="d-flex gap-2 align-items-center"><input type="checkbox" name="active" value="1" '.($row->active?'checked':'').'>Active</label><button class="btn btn-sm btn-light mt-1">Save</button></form>');
        if(in_array($resource,['users','roles','invoices','expenses','customers','shifts','fuels','nozzles','shift-types'],true))$table->rawColumns(['actions','contact','receipt']);
        return $table->toJson();
    }
}
